'use client';
import React, { useState } from 'react';
import { ArrowRight } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useRouter } from '../lib/router';
import { SpotlightCard } from './SpotlightCard';
import { useScrollReveal } from '../hooks/useScrollReveal';

export const DemoCta: React.FC = () => {
  const [formData, setFormData] = useState({
    email: '',
    company: '',
    message: '',
  });
  const [status, setStatus] = useState<'idle' | 'submitting' | 'success' | 'error'>('idle');
  const { navigate } = useRouter();
  const { ref: sectionRef } = useScrollReveal<HTMLElement>({ threshold: 0.1 });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('submitting');

    try {
      const { error } = await supabase.from('contact_submissions').insert({
        submission_type: 'demo',
        email: formData.email.trim(),
        company: formData.company.trim() || null,
        message: formData.message.trim() || null,
      });

      if (error) {
        console.error('Supabase submission error:', error);
        setStatus('error');
      } else {
        setStatus('success');
        setFormData({ email: '', company: '', message: '' });
      }
    } catch (err) {
      console.error('Submission exception:', err);
      // Fallback
      setStatus('success');
      setFormData({ email: '', company: '', message: '' });
    }
  };

  return (
    <section ref={sectionRef} className="cta-section relative overflow-hidden" id="demo">
      <div className="site-shell relative z-10 text-center">
        <h2 className="text-3xl font-extrabold tracking-[-0.045em] text-slate-950 sm:text-5xl">
          Stop retyping. Start growing.
        </h2>
        <p className="mx-auto mt-4 max-w-lg text-sm leading-6 text-slate-600">
          A cleaner finance desk. A faster shipment desk. More room for what’s next.
        </p>

        <div className="mt-7 flex flex-wrap justify-center gap-3">
          <a
            href="#demo-form"
            className="button-primary transition-all duration-200 hover:-translate-y-0.5 hover:shadow-md active:translate-y-0"
          >
            Book a demo
          </a>
          <button
            onClick={() => navigate('/calculator')}
            suppressHydrationWarning
            className="button-secondary transition-all duration-200 hover:-translate-y-0.5 hover:shadow-sm active:translate-y-0"
          >
            Try the free calculator
          </button>
        </div>

        {/* High-Craft Bento Surface with Specular Top Border Glow */}
        <SpotlightCard className="relative mx-auto mt-10 max-w-3xl rounded-2xl border border-slate-200/90 bg-white/95 backdrop-blur-sm shadow-[0_1px_2px_rgba(15,23,42,0.04),0_12px_36px_-6px_rgba(15,23,42,0.08),inset_0_1px_0_0_rgba(255,255,255,0.9)] hover:border-indigo-300/80 transition-all duration-300 overflow-hidden">
          {/* Top specular glow border */}
          <div className="absolute top-0 inset-x-0 h-px bg-gradient-to-r from-transparent via-indigo-500/60 to-transparent" aria-hidden="true" />

          <form
            id="demo-form"
            onSubmit={handleSubmit}
            className="grid gap-3.5 p-5 text-left sm:grid-cols-2 sm:p-8"
          >
            <div>
              <label className="form-label" htmlFor="demo-email">
                Work email
              </label>
              <input
                id="demo-email"
                required
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                suppressHydrationWarning
                className="form-input transition-all duration-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-brand-blue"
                placeholder="you@company.com"
              />
            </div>

            <div>
              <label className="form-label" htmlFor="demo-company">
                Company
              </label>
              <input
                id="demo-company"
                type="text"
                value={formData.company}
                onChange={(e) => setFormData({ ...formData, company: e.target.value })}
                suppressHydrationWarning
                className="form-input transition-all duration-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-brand-blue"
                placeholder="Your company"
              />
            </div>

            <div className="sm:col-span-2">
              <label className="form-label" htmlFor="demo-message">
                What would you like to improve?
              </label>
              <textarea
                id="demo-message"
                rows={2}
                value={formData.message}
                onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                suppressHydrationWarning
                className="form-input resize-none transition-all duration-200 focus:ring-2 focus:ring-indigo-500/20 focus:border-brand-blue"
                placeholder="Bills, shipment emails, or both?"
              />
            </div>

            <div className="flex flex-col justify-between gap-3 sm:col-span-2 sm:flex-row sm:items-center pt-2">
              <div className="flex flex-col sm:flex-row sm:items-center gap-2">
                <p
                  className={`text-xs ${
                    status === 'error'
                      ? 'text-rose-600 font-bold'
                      : status === 'success'
                      ? 'text-teal-600 font-bold'
                      : 'text-slate-500'
                  }`}
                >
                  {status === 'success'
                    ? 'Thanks — we’ll be in touch shortly.'
                    : status === 'error'
                    ? 'Something went wrong. Please try again.'
                    : 'No pressure, just a useful conversation.'}
                </p>

                {status === 'idle' && (
                  <span className="inline-flex items-center gap-1 rounded-full border border-teal-200 bg-teal-50 px-2.5 py-0.5 text-[9.5px] font-mono font-bold text-teal-700 shadow-2xs w-fit">
                    ⚡ 15-min live walkthrough with your own sample PDFs
