.documentIcon { position: relative; display: grid; place-items: center; width: 32px; height: 34px; flex-shrink: 0; border-radius: 5px; color: #9ba9b3; background: #fff; }
.documentIcon > span { position: absolute; bottom: 6px; right: 2px; color: #a97764; font-size: 6px; font-weight: 800; }
.plusIcon { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 5px; flex-shrink: 0; color: #5bb6a0; background: #e1f3ed; }
