.helpButton { position: absolute; bottom: 24px; right: 27px; width: 38px; height: 38px; display: grid; place-items: center; border-radius: 50%; background: #5250c8; color: #fff; box-shadow: 0 5px 13px rgb(75 72 159 / 20%); cursor: pointer; }
.helpButton svg { stroke: #5250c8; stroke-width: 1.3; }
