.scene {
  --motion-state: running;
  position: relative;
  width: 100%;
  min-width: 620px;
  aspect-ratio: 800 / 370;
  container-type: inline-size;
  isolation: isolate;
  color: #404747;
  font-size: clamp(10px, 1.45cqw, 12px);
  line-height: 1.4;
}
.scene[data-running='false'] { --motion-state: paused; }
.connections { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; overflow: visible; }
.incomingTrack { stroke: #82bbaa; stroke-width: 1.6; opacity: 0.6; animation: intakeTrack 5.5s linear infinite; animation-play-state: var(--motion-state); }
.straightTrack { stroke: #a5adb3; stroke-width: 1.5; }
.arrow { stroke: #a5adb3; stroke-width: 1.5; fill: #a5adb3; }
.elbowTrack { stroke: #70b69b; stroke-width: 1.8; }
.port, .outputPort { fill: #24b58a; stroke: #a2dfc8; stroke-width: 1; }
.destinationPort { fill: #fff; stroke: #70bd9e; stroke-width: 2; }
.inputHalo, .destinationHalo { fill: #75f3ca; opacity: 0; transform-box: fill-box; transform-origin: center; animation: portGlow 5.5s ease-out infinite; animation-play-state: var(--motion-state); }
.destinationHalo { animation-delay: 1s; }
.packet { stroke: #f4fffa; stroke-width: 6; stroke-linecap: round; stroke-dasharray: 7 100; filter: drop-shadow(0 0 3px #2ce7a7) drop-shadow(0 0 7px #64e4b6); opacity: 0; animation-duration: 5.5s; animation-timing-function: linear; animation-iteration-count: infinite; animation-play-state: var(--motion-state); }
.incomingPacket { animation-name: incomingFlow; }
.lowerPacket { animation-name: incomingFlow; animation-delay: -0.2s; stroke-width: 3.5; }
.elbowPacket { animation-name: elbowFlow; animation-duration: 1.65s; stroke-width: 7; }

.incoming { position: absolute; left: 3.4%; top: 12.4%; width: 19%; }
.stepHeading h3, .resultTitle h3 { margin: 3px 0 0; font-weight: 700; font-size: clamp(11px, 1.7cqw, 14px); line-height: 1.35; color: #3f4649; }
.stepHeading p { margin-top: 2px; font-size: clamp(8px, 1.2cqw, 10px); color: #8d969c; white-space: nowrap; }
.stepLine { display: flex; align-items: center; justify-content: space-between; gap: 4px; }
.kicker { color: #868b8d; font-size: clamp(9px, 1.3cqw, 11px); }
.ingestion { display: inline-flex; color: #8a87b6; background: #e8e9f7; border-radius: 3px; padding: 1px 4px; font-size: clamp(7px, 1cqw, 8px); }
.invoice { margin-top: 9px; padding: 8px; border: 1px solid #e8e9e9; border-radius: 6px; background: #fff; box-shadow: 0 5px 12px rgb(39 56 66 / 10%); }
.invoiceHeading { display: flex; align-items: center; gap: 6px; }
.invoiceHeading strong { display: block; white-space: nowrap; font-size: clamp(8px, 1.25cqw, 10px); color: #555b5f; }
.invoiceHeading small { display: block; margin-top: 1px; color: #989c9f; font-size: clamp(7px, 1cqw, 8px); }
.pdf { position: relative; display: inline-flex; flex-shrink: 0; color: #d6d8db; }
.pdf b { position: absolute; bottom: 0; left: -1px; background: #e88b98; color: white; border-radius: 2px; padding: 0 2px; font-size: 6px; }
.smallFile { margin-left: auto; color: #b9bec2; }
.amount { display: flex; align-items: center; justify-content: space-between; gap: 4px; margin-top: 14px; color: #96999b; font-size: clamp(8px, 1.15cqw, 10px); }
.amount strong { color: #41474b; font-size: clamp(9px, 1.35cqw, 11px); }
.invoiceLines { display: flex; flex-direction: column; gap: 3px; margin-top: 7px; }
.invoiceLines span { height: 3px; background: #ebeced; border-radius: 1px; }
.invoiceLines span:nth-child(2) { width: 80%; }
.invoiceLines span:nth-child(3) { width: 96%; }
.invoiceFooter { display: flex; justify-content: space-between; gap: 5px; margin-top: 16px; font-size: clamp(6px, 0.95cqw, 8px); color: #b8bec0; }
.invoiceFooter span:first-child { color: #63af91; font-weight: 700; }

.reading { position: absolute; left: 33.125%; top: 8.65%; width: 23.5%; padding: 1.5cqw; border: 1px solid #e7e9e9; border-radius: 7px; background: #fff; box-shadow: 0 8px 15px rgb(45 58 70 / 12%); }
.extraction { position: relative; margin-top: 1.375cqw; padding: 1.25cqw; overflow: hidden; border: 1px solid #d6e8e2; border-radius: 6px; background: linear-gradient(120deg, #e4f4eb, #edf7f3); }
.extractionTop { display: flex; align-items: center; justify-content: space-between; color: #91b9ae; }
.sheetIcon { width: 28px; height: 28px; display: grid; place-items: center; border-radius: 4px; background: #b8e8d5; color: #4caf8c; }
.extractionText { display: flex; align-items: center; justify-content: space-between; gap: 4px; margin-top: 9px; color: #7d9f91; }
