'use client';
import React, { useState, useEffect } from 'react';
import { 
  Play, 
  Pause, 
  RotateCcw, 
  CheckCircle2, 
  ShieldCheck, 
  Database, 
  Sparkles, 
  Mail, 
  Video as VideoIcon,
  Layers
} from 'lucide-react';
import { walkthroughChapters, pipelineInvoice, pipelineVoucher } from './mockData';
import { VideoPlayer } from '@/src/components/video/VideoPlayer';
import { videosConfig } from '@/src/content/videos';

interface WalkthroughViewProps {
  walkthroughVideoUrl?: string;
  isPaused?: boolean;
}

export const WalkthroughView: React.FC<WalkthroughViewProps> = ({ 
  walkthroughVideoUrl,
  isPaused = false 
}) => {
  const [displayMode, setDisplayMode] = useState<'storyboard' | 'player'>('storyboard');
  const [isPlaying, setIsPlaying] = useState<boolean>(true);
  const [currentChapter, setCurrentChapter] = useState<number>(0);
  const [currentTimeSec, setCurrentTimeSec] = useState<number>(14); // start at 0:14

  const totalDurationSec = 120; // 2:00

  // Play/pause toggle for storyboard mode
  const togglePlay = () => {
    setIsPlaying((prev) => !prev);
  };

  // Chapter Jump
  const handleJumpChapter = (chapterIndex: number) => {
    setCurrentChapter(chapterIndex);
    setCurrentTimeSec(walkthroughChapters[chapterIndex].timeSec + 5);
  };

  // Scrubber click
  const handleScrubberClick = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const clickRatio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    const targetSec = Math.floor(clickRatio * totalDurationSec);
    setCurrentTimeSec(targetSec);

    // Map time to chapter
    if (targetSec < 30) setCurrentChapter(0);
    else if (targetSec < 60) setCurrentChapter(1);
    else if (targetSec < 90) setCurrentChapter(2);
    else setCurrentChapter(3);
  };

  // Playback timer for storyboard mode
  useEffect(() => {
    if (displayMode !== 'storyboard') return;
    if (!isPlaying || isPaused) return;
    if (typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setIsPlaying(false);
      return;
    }

    const interval = setInterval(() => {
      setCurrentTimeSec((prev) => {
        const next = (prev + 1) % totalDurationSec;
        if (next < 30) setCurrentChapter(0);
        else if (next < 60) setCurrentChapter(1);
        else if (next < 90) setCurrentChapter(2);
        else setCurrentChapter(3);
        return next;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [isPlaying, isPaused, displayMode]);

  // Format seconds to mm:ss
  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  const progressPercent = (currentTimeSec / totalDurationSec) * 100;
  const activeChapterData = walkthroughChapters[currentChapter];

  return (
    <div className="w-full h-full flex flex-col justify-between rounded-xl bg-slate-950 border border-slate-800 text-white p-3 sm:p-4 shadow-xl select-none">

      {/* ================= TOP BAR: MODE SWITCHER & DEMO BADGE ================= */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-800/80 pb-2.5">

        {/* Mode Switcher Pill */}
        <div className="flex items-center gap-1 font-mono text-[10px]" role="tablist" aria-label="Walkthrough presentation mode">
          <button
            type="button"
            role="tab"
            aria-selected={displayMode === 'player'}
            onClick={() => setDisplayMode('player')}
            className={`inline-flex items-center gap-1.5 rounded px-2.5 py-1 transition-all cursor-pointer outline-none ${
              displayMode === 'player'
                ? 'bg-[#4F46E5] text-white font-bold shadow-xs border border-indigo-400'
                : 'bg-slate-900 text-slate-400 border border-slate-800 hover:text-white hover:bg-slate-800'
            }`}
          >
            <VideoIcon size={11} />
            <span>Video Player</span>
          </button>

          <button
            type="button"
            role="tab"
            aria-selected={displayMode === 'storyboard'}
            onClick={() => setDisplayMode('storyboard')}
            className={`inline-flex items-center gap-1.5 rounded px-2.5 py-1 transition-all cursor-pointer outline-none ${
              displayMode === 'storyboard'
                ? 'bg-[#4F46E5] text-white font-bold shadow-xs border border-indigo-400'
                : 'bg-slate-900 text-slate-400 border border-slate-800 hover:text-white hover:bg-slate-800'
            }`}
          >
            <Layers size={11} />
            <span>Interactive Storyboard</span>
          </button>
        </div>

        {/* Illustrative Demo Badge */}
        <span className="inline-flex items-center gap-1 rounded bg-slate-900 border border-slate-700/80 px-2 py-0.5 font-mono text-[9.5px] text-slate-400 self-start sm:self-auto">
          <Sparkles size={10} className="text-indigo-400" />
          Illustrative demo
        </span>
      </div>

      {/* ================= CONDITIONAL DISPLAY MODE ================= */}
      {displayMode === 'player' ? (
        <div className="my-2 flex-1 flex flex-col justify-center">
          <VideoPlayer
