export interface VideoChapter {
  id: string;
  timeSec: number;
  label: string;
  title: string;
  description: string;
}

export interface VideoConfig {
  id: string;
  title: string;
  description: string;
  type: 'loop' | 'player' | 'modal' | 'facade' | 'slot';
  sources?: {
    webm?: string;
    mp4?: string;
  };
